import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Identify strong candidates using t-test and effect size
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
        auc = 0.5 + 0.5 * np.abs(mean_diff) / np.std(feats.x[:, i])  # Simplified AUC estimate
        candidates.append((fid, abs(mean_diff), abs(t_stat), p_val, auc))

    candidates.sort(key=lambda x: x[2], reverse=True)  # Sort by t-statistic

    # Remove near-duplicates based on correlation
    keep = []
    correlated = set()
    for i, (fid1, _, _, _, _) in enumerate(candidates):
        if fid1 in correlated:
            continue
        keep.append(i)
        # Check correlations with subsequent features
        for j, (fid2, _, _, _, _) in enumerate(candidates[i+1:], i+1):
            if fid2 in correlated:
                continue
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) >= 0.6:
                correlated.add(fid2)

    selected = [candidates[i][0] for i in keep[:MAX_DRIVERS]]

    # If no strong candidate, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression components
    columns = list(selected)
    loadings = {fid: 1.0 for fid in columns}

    # Add interaction terms between highly correlated pairs
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) >= 0.6:
                products.append((fid1, fid2))

    # Select top drivers based on effect size, but limit to MAX_DRIVERS
    drivers = [fid for fid, _, _, _, _ in sorted(candidates[:MAX_DRIVERS], 
                                                 key=lambda x: x[1], reverse=True)]
    drivers = drivers[:MAX_DRIVERS]  # Ensure we don't exceed maximum

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

